            # stamp) -- the stored call never goes, and the row ends here.
            emit([lstore([("s-dfb", {"operation": "delete", "table": "state",
                                     "where": {"key": spec_key("spec_fb", session, turn)}}),
                          ("s-set", {"operation": "delete", "table": "state",
                                     "where": {"key": spec_key("spec", session, turn),
                                               "value": raw}})], "done", call, ""),
                  act(call, {"do": "unsent", "fb": fb, "round": rnd})])
        # Dropped without an answer (or gone): the stored call goes.
        emit([lstore([("s-dfb", {"operation": "delete", "table": "state",
                                 "where": {"key": spec_key("spec_fb", session, turn)}})],
                     "done", call, ""),
              act(call, {"do": "fb_go", "fb": fb, "round": rnd})])
    if phase == "delta-send":
        # GH #1279: the reused call of a delta stamp. The move took: it goes.
        # Lost: the turn's normal curate stored its call as the fallback of
        # this spec curate (`await`) -- that call goes, this one never went.
        st = state_of(lg, "f-dread")
        fb_key = DELTA_FB_KEY + "%s#%s" % (session, turn)
        mine = jd(st.get(fb_key, ""))
        ops = [("d-dfb", {"operation": "delete", "table": "state", "where": {"key": fb_key}})]
        a = {"do": "delta", "won": True, "mine": mine, "fb": None, "s": session, "t": turn,
             "round": rnd}
        if (lg.get("f-sdelta") or {}).get("rows_affected", 0) != 1:
            raw = st.get(spec_key("spec", session, turn), "")
            row = jd(raw)
            a["won"] = False
            a["lost"] = str(row.get("state") or "none")
            if str(row.get("state") or "") == "await" and str(row.get("call") or "") == call:
                a["fb"] = jd(st.get(spec_key("spec_fb", session, turn), ""))
                ops += [("d-set", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec", session, turn),
                                             "value": raw}}),
                        ("d-sfb", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec_fb", session, turn)}})]
        emit([lstore(ops, "done", call, ""), act(call, a)])
    if phase == "done":
        emit([])
    sys.stderr.write("curator/lead: a message with no lane it serves (%r/%r) -- dropped\n"
                     % (lane, phase))
    emit([])
